# renumerate.py

version = "1.0.0"

import bisect
from collections import defaultdict


# this code was generated by gemini 
def find_all_boundary_rectangles(points_list):
    """
    Finds all valid rectangles having a point on each of its 4 boundaries.
    
    Parameters:
    points_list (list): A list of tuples (id: string, x: float, y: float)
    
    Returns:
    dict: A mapping of rectangle IDs to their bounds and covered point IDs.
    """
    # 1. Store points in a dictionary by their ID
    points_dict = {pid: {"x": px, "y": py} for pid, px, py in points_list}
    
    # 2. Group points by X coordinate for efficient slicing
    x_to_pts = defaultdict(list)
    for pid, px, py in points_list:
        x_to_pts[px].append((py, pid))  # Store as (y, id) to sort by Y easily
        
    unique_x = sorted(list(x_to_pts.keys()))
    rectangles_output = {}
    rect_counter = 1
    
    # Iterate over all pairs of X boundaries
    for i in range(len(unique_x)):
        x_min = unique_x[i]
        
        # Pull points incrementally between x_min and x_max
        current_pts = []
        
        for j in range(i, len(unique_x)):
            x_max = unique_x[j]
            current_pts.extend(x_to_pts[x_max])
            
            # Left and right boundary Y arrays for fast constraint checks
            left_ys = sorted([item[0] for item in x_to_pts[x_min]])
            right_ys = sorted([item[0] for item in x_to_pts[x_max]])
            
            # Sort current sweep-line slice by Y-coordinate
            current_pts.sort(key=lambda item: item[0])
            all_unique_ys = sorted(list(set(item[0] for item in current_pts)))
            
            start_pt_idx = 0
            
            for y_min in all_unique_ys:
                # Find smallest left Y >= y_min
                idx_l = bisect.bisect_left(left_ys, y_min)
                if idx_l == len(left_ys): continue
                
                # Find smallest right Y >= y_min
                idx_r = bisect.bisect_left(right_ys, y_min)
                if idx_r == len(right_ys): continue
                
                # Minimum height constraint to close left/right boundaries
                y_start = max(left_ys[idx_l], right_ys[idx_r])
                y_max_choices = [y for y in all_unique_ys if y >= y_start]
                if not y_max_choices: continue
                
                while start_pt_idx < len(current_pts) and current_pts[start_pt_idx][0] < y_min:
                    start_pt_idx += 1
                
                # Accumulate points incrementally as y_max goes higher
                active_point_ids = []
                pt_idx = start_pt_idx
                
                for y_max in y_max_choices:
                    while pt_idx < len(current_pts) and current_pts[pt_idx][0] <= y_max:
                        active_point_ids.append(current_pts[pt_idx][1])
                        pt_idx += 1
                    
                    # 3. Format output with sequentially generated rectangle IDs
                    rect_id = f"rectangle{rect_counter}"
                    rectangles_output[rect_id] = {
                        "bounds": {"x_min": x_min, "x_max": x_max, "y_min": y_min, "y_max": y_max},
                        "covered_points": list(active_point_ids)
                    }
                    rect_counter += 1
                        
    return rectangles_output, points_dict
